<?php /** @var array $rows @var int $year */ ?>
<div class="page-head"><div><h1><?= icon('file') ?> <?= e(t('gov.report')) ?> — <?= (int)$year ?></h1><p class="sub"><?= e(t('gov.report_hint')) ?></p></div>
  <form method="get" action="<?= e(url('governance/report')) ?>" class="filters"><div class="field"><label for="year"><?= e(t('sha.year')) ?></label><input type="number" id="year" name="year" min="2000" max="2100" value="<?= (int)$year ?>"></div><div class="field"><button class="btn secondary" type="submit"><?= e(t('common.apply')) ?></button></div></form>
  <div class="actions noprint"><a class="btn secondary" href="<?= e(url('governance')) ?>"><?= e(t('common.back')) ?></a><button class="btn" type="button" data-print><?= e(t('common.print')) ?></button></div></div>
<div class="table-wrap"><table class="data"><thead><tr><th><?= e(t('gov.b_name')) ?></th><th class="num"><?= e(t('gov.held')) ?></th><th class="num"><?= e(t('gov.required')) ?></th><th class="num"><?= e(t('gov.no_quorum_n')) ?></th><th class="num"><?= e(t('gov.avg_attendance')) ?></th><th><?= e(t('gov.verdict')) ?></th></tr></thead><tbody>
<?php if (!$rows): ?><tr><td colspan="6" class="empty"><?= e(t('common.no_results')) ?></td></tr><?php endif; ?>
<?php foreach ($rows as $r): $issues = []; if ((int)$r['held_n'] < (int)$r['min_meetings_per_year']) $issues[] = t('gov.issue_meetings'); if ((int)$r['no_quorum_n'] > 0) $issues[] = t('gov.issue_quorum'); if (!(int)$r['chairs_n']) $issues[] = t('gov.no_chair'); ?>
<tr><td><a href="<?= e(url('governance/' . $r['id'])) ?>"><?= e($r['name']) ?></a></td><td class="num"><?= (int)$r['held_n'] ?></td><td class="num"><?= (int)$r['min_meetings_per_year'] ?></td><td class="num"><?= (int)$r['no_quorum_n'] ?></td><td class="num"><?= (int)$r['avg_att'] ?>%</td>
<td><?= $issues ? '<span class="badge danger">' . e(implode(' · ', $issues)) . '</span>' : '<span class="badge ok">' . e(t('gov.compliant')) . '</span>' ?></td></tr><?php endforeach; ?></tbody></table></div>
